/// <summary>
///     The <c>SalesLineBackOrderFrm_GridFilterCustAccountFld_Extension</c> class is the extension for <c>SalesLineBackOrder</c>
/// </summary>
[ExtensionOf(formControlStr(SalesLineBackOrder, GridFilterCustAccount))]
final class SalesLineBackOrderFrm_GridFilterCustAccountFld_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
 /// <returns>boolean</returns>
 public boolean modified()
 {
     boolean         retVal;
     CustAccount     qValue;

     FormDataSource  locSalesTableDS;
     FormDataSource  locSalesLineDS;

     locSalesTableDS = element.SalesTable_DS;
     locSalesLineDS  = element.SalesLine_DS;

     retVal = next modified();

     qValue = element.GridFilterCustAccount.valueStr();

     if (qValue != '')
     {
         SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, CustAccount)).value(queryValue(qValue));
     }
     else
     {
         SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, CustAccount)).value(SysQueryRangeUtil::valueUnlimited());
     }

     locSalesLineDS.executeQuery();

     return retVal;
 }
